properties.property:
[
  {
    "text": "Hello, planeswalker. Do you appreciate the fine art of ante – the wagering on duels to the death?",
    "options": [
      {
        "name": "Yes, I play with ante enabled",
        "text": "I have many mighty spells to tip the scales of such wagers in your favor! You could win countless more spells from your foes with such tools – contracts from below, demonic attorneys, jeweled birds, bronze tablets and more… all for just a tiny sliver of your soul. What do you say?",
        "options": [
          {
            "name": "Accept the deal",
            "text": "A wise decision... no refunds, now.",
            "action": [
              {
                "deleteMapObject": -1,
                "grantRewards": [
                  { "type": "life", "count": -2 },
                  { "type": "card", "cardName": "Contract from Below|LEA", "count": 4 },
                  { "type": "card", "cardName": "Demonic Attorney|LEA", "count": 4 },
                  { "type": "card", "cardName": "Jeweled Bird|ARN", "count": 4 },
                  { "type": "card", "cardName": "Bronze Tablet|ATQ", "count": 4 },
                  { "type": "card", "cardName": "Darkpact|LEA", "count": 4 },
                  { "type": "card", "cardName": "Timmerian Fiends|HML", "count": 4 }
                ]
              }
            ]
          },
          {
            "name": "Decline",
            "text": "Well, perhaps I shall take your whole soul myself!",
            "action": [
              { "battleWithActorID": -1 }
            ]
          }
        ]
      },
      {
        "name": "No, I don't use ante",
        "text": "Well, I still have something quite magnificent to offer you – fabulous wealth in exchange for just a tiny sliver of your soul. How does 20,000 gold sound? A fortune fit for a king, I would say! And well-deserved by a mighty and noble adventurer such as yourself. So, do we have a deal?",
        "options": [
          {
            "name": "Accept the deal",
            "text": "A wise decision... no refunds, now.",
            "action": [
              {
                "deleteMapObject": -1,
                "addGold": 20000,
                "grantRewards": [
                  { "type": "life", "count": -2 }
                ]
              }
            ]
          },
          {
            "name": "Decline",
            "text": "Well, perhaps I shall take your whole soul myself!",
            "action": [
              { "battleWithActorID": -1 }
            ]
          }
        ]
      }
    ]
  }
]
